const safeExpr = (expr) => {
  // Parse arithmetic without eval or new Function. Reject unknown tokens and identifiers.
  const input = String(expr || '').trim().toLowerCase().replace(/\*\*/g, '^');
  if (!input || input.length > 130) throw Error('Expression must be 1–130 characters.');
  const tokens = [];
  const matcher = /\s*(?:((?:\d+(?:\.\d*)?|\.\d+)(?:e[+\-]?\d+)?)|([a-z]+)|([()+\-*\/^%,]))/gy;
  let at = 0;
  while (at < input.length) {
    matcher.lastIndex = at;
    const part = matcher.exec(input);
    if (!part || matcher.lastIndex === at) throw Error('Unsupported character or expression.');
    tokens.push(part[1] !== undefined ? {kind:'number', value:Number(part[1])} :
                part[2] !== undefined ? {kind:'name', value:part[2]} : {kind:'symbol', value:part[3]});
    at = matcher.lastIndex;
  }
  if (tokens.length > 130) throw Error('Expression is too complex.');
  let i = 0;
  const peek = () => tokens[i]?.value;
  const take = sym => { if (peek() === sym) { i++; return true; } return false; };
  const requireToken = sym => { if (!take(sym)) throw Error('Expected "' + sym + '".'); };
  const funcs = Object.freeze({ sin:Math.sin, cos:Math.cos, tan:Math.tan,
    sqrt:Math.sqrt, abs:Math.abs, log:Math.log, ln:Math.log, exp:Math.exp,
    pow:Math.pow, floor:Math.floor, ceil:Math.ceil, round:Math.round });
  const expression = () => {
    let left = term();
    while (peek() === '+' || peek() === '-') {
      const operator = tokens[i++].value, right = term(), prev = left;
      left = x => operator === '+' ? prev(x) + right(x) : prev(x) - right(x);
    }
    return left;
  };
  const term = () => {
    let left = unary();
    while (peek() === '*' || peek() === '/' || peek() === '%') {
      const operator = tokens[i++].value, right = unary(), prev = left;
      left = x => operator === '*' ? prev(x) * right(x) : operator === '/' ? prev(x) / right(x) : prev(x) % right(x);
    }
    return left;
  };
  const unary = () => {
    if (take('+')) return unary();
    if (take('-')) { const val = unary(); return x => -val(x); }
    return power();
  };
  const power = () => {
    const left = primary();
    if (take('^')) { const right = unary(); return x => Math.pow(left(x), right(x)); }
    return left;
  };
  const primary = () => {
    if (take('(')) { const val = expression(); requireToken(')'); return val; }
    const token = tokens[i++];
    if (!token) throw Error('Incomplete expression.');
    if (token.kind === 'number') return () => token.value;
    if (token.kind !== 'name') throw Error('Unexpected character in expression.');
    if (token.value === 'x') return x => Number(x);
    if (token.value === 'pi') return () => Math.PI;
    if (token.value === 'e') return () => Math.E;
    const fn = funcs[token.value];
    if (!fn) throw Error('Only supported math functions are allowed.');
    requireToken('(');
    const first = expression();
    let second = null;
    if (take(',')) second = expression();
    requireToken(')');
    if ((token.value === 'pow') !== (second !== null)) throw Error('Use pow(base, exponent); all other functions take one argument.');
    return second ? x => fn(first(x), second(x)) : x => fn(first(x));
  };
  const parsed = expression();
  if (i !== tokens.length) throw Error('Unexpected extra characters in expression.');
  return parsed;
};
