function renderLearning(){set('sdMetricCards',data.stats.seen||0);set('sdMetricKnown',(data.stats.seen?Math.round(100*data.stats.known/data.stats.seen):0)+'%');set('sdMetricFocus',data.stats.focus||0);const box=$('sdLearningTopics');box.replaceChildren();data.topics.forEach(t=>{const row=document.createElement('div');row.className='sd-task';const name=document.createElement('span');name.textContent=t.name+' · '+(t.confident?'Comfortable':'Needs review');const b=document.createElement('button');b.textContent=t.confident?'Review again':'Mark comfortable';b.onclick=()=>{t.confident=!t.confident;save();renderLearning()};const del=document.createElement('button');del.textContent='×';del.onclick=()=>{data.topics=data.topics.filter(x=>x.id!==t.id);save();renderLearning()};row.append(name,b,del);box.append(row)})}$('sdLearningAdd').onclick=()=>{const v=$('sdLearningTopic').value.trim();if(!v)return;data.topics.push({id:id(),name:v,confident:false});$('sdLearningTopic').value='';save();renderLearning()};$('sdLearningPlan').onclick=()=>{const need=data.topics.filter(t=>!t.confident).map(t=>t.name);const done=data.topics.filter(t=>t.confident).map(t=>t.name);set('sdLearningOutput',need.length?'Suggested next session:\n1. Review '+need.slice(0,3).join(', ')+'.\n2. Make flashcards from your notes.\n3. Self-test before revealing answers.\n4. Revisit topics you missed tomorrow.\n\nTopics you marked comfortable: '+(done.join(', ')||'None yet.'):'Add a topic marked Needs review to get a targeted practice plan.')};renderLearning();
