const sdDate=(d)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
let displayedMonth=new Date();displayedMonth=new Date(displayedMonth.getFullYear(),displayedMonth.getMonth(),1);
let selectedDate=sdDate(new Date()),activeLesson='';
function sdCreate(tag,text,className){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el}
function sdEmpty(root,text){root.replaceChildren(sdCreate('p',text,'sub'))}
function sdStatus(id,text){set(id,text)}
function findSkill(topic){return data.skills.find(s=>s.name.toLocaleLowerCase('en-US')===String(topic||'').trim().toLocaleLowerCase('en-US'))}
function noteSkill(topic,score,reason){const name=String(topic||'').trim().slice(0,100);if(!name)return;
 let row=findSkill(name);if(!row){row={id:id(),name,score:50,attempts:0,updated:Date.now(),notes:''};data.skills.push(row)}
 row.score=Math.max(0,Math.min(100,Math.round(typeof score==='number'?score:row.score)));
 row.attempts=(row.attempts||0)+1;row.updated=Date.now();if(reason)row.notes=reason;save();renderSkills()}
function renderSkills(){const box=$('sdSkillRows');if(!box)return;box.replaceChildren();const overall=$('sdSkillOverall');if(overall){overall.textContent=data.skills.length?'Overall confidence: '+Math.round(data.skills.reduce((n,s)=>n+s.score,0)/data.skills.length)+'/100 · '+data.skills.length+' rated skill'+(data.skills.length===1?'':'s'):'Overall confidence: not rated yet'};
 const items=[...data.skills].sort((a,b)=>a.score-b.score);
 if(!items.length)return sdEmpty(box,'No skill ratings yet. Add a skill or complete a topic lesson to get started.');
 items.forEach(sk=>{const wrap=sdCreate('div',undefined,'sd-skill-item');const header=sdCreate('div',undefined,'sd-skill-head');
 const title=sdCreate('b',sk.name);const score=sdCreate('strong',`${sk.score}/100`,'sd-skill-score');header.append(title,score);
 const track=sdCreate('div',undefined,'sd-skill-track'),bar=sdCreate('div');bar.style.width=Math.min(100,Math.max(0,sk.score))+'%';track.append(bar);
 const foot=sdCreate('div',undefined,'row');const hint=sdCreate('small',sk.score<=40?'Priority: needs support':sk.score<=70?'Developing skill':'Feeling confident','sd-skill-foot');foot.append(hint);
 for(const [label,delta] of [['−10',-10],['+10',10]]){const btn=sdCreate('button',label,'btn ghost small');btn.type='button';btn.title='Adjust self-rating '+label;btn.onclick=()=>noteSkill(sk.name,sk.score+delta,'Self-rating updated');foot.append(btn)}
 const practice=sdCreate('button','Practice','btn secondary small');practice.onclick=()=>{$('sdTopicInput').value=sk.name;showPane('topic');$('sdTopicInput').focus()};foot.append(practice);
 wrap.append(header,track,foot);box.append(wrap)})}
$('sdSkillAdd').onclick=()=>{const v=$('sdSkillNew').value.trim();if(!v)return;noteSkill(v,50,'Added for review');$('sdSkillNew').value=''};
$('sdSkillNew').addEventListener('keydown',e=>{if(e.key==='Enter')$('sdSkillAdd').click()});
$('sdFlashcardsFromStruggles').onclick=()=>{
 const needs=[...data.skills].sort((a,b)=>a.score-b.score).filter(a=>a.score<=75).slice(0,9).map(x=>x.name+' (self-rating '+x.score+'/100)');
 const notes=data.topics.filter(t=>!t.confident).map(t=>t.name).slice(0,8);
 const list=[...new Set([...needs,...notes])];if(!list.length){set('sdQuizStatus','Mark a topic as “I still need to improve”, or give a skill a score under 76 in Skills & progress.');return}
 $('sdQuizSource').value='Create targeted review flashcards for my weakest skills. Focus on common misunderstandings and include gentle step-by-step explanations: '+list.join('; ');
 set('sdQuizStatus','Loaded '+list.length+' skill(s). Select Generate flashcards to create your practice deck.');$('sdQuizSource').scrollIntoView({behavior:'smooth',block:'center'});
};
async function lessonExplain(extra=''){
 const topic=$('sdTopicInput').value.trim();if(!topic)return sdStatus('sdTopicStatus','Enter a topic first.');activeLesson=topic;
 const btn=$('sdTopicExplain');btn.disabled=true;sdStatus('sdTopicStatus','Preparing your lesson…');$('sdTopicExplanation').textContent='Thinking through the concept…';
 try{const prompt=`Teach this topic at ${level()} level: ${topic}. Give (1) a clear definition, (2) how or why it works, (3) one familiar real-world example, (4) 3 quick check-for-understanding questions without answers immediately, and (5) a short summary. Use approachable explanations, not a completed assignment. ${extra}`;
 const answer=await ai('You are a warm, accurate, Socratic tutor who teaches understanding instead of doing a learner’s homework. Ask the learner to reason through questions. '+context(),prompt,2300);
 set('sdTopicExplanation',answer);$('sdTopicReflection').hidden=false;sdStatus('sdTopicStatus','Read the lesson, then choose how well you understand it.');
 }catch(e){sdStatus('sdTopicStatus',e.message);set('sdTopicExplanation','Connect a working AI model in Settings to receive a custom explanation. You can still track topics and assignments offline.')}
 finally{btn.disabled=false}
}
$('sdTopicExplain').onclick=()=>lessonExplain();
$('sdTopicReflection').querySelectorAll('[data-understand]').forEach(b=>b.onclick=()=>{
 const v=b.dataset.understand,skill=findSkill(activeLesson),was=skill?.score??50;
 const newScore=v==='understand'?Math.max(85,was+15):v==='improve'?Math.min(65,was-7):Math.min(40,was-15);
 noteSkill(activeLesson,newScore,v==='understand'?'Understanding confirmed':v==='improve'?'Still improving':'Needs more explanation');
 const topic=data.topics.find(t=>t.name.toLowerCase()===activeLesson.toLowerCase());if(topic)topic.confident=v==='understand';else data.topics.unshift({id:id(),name:activeLesson,confident:v==='understand'});save();renderLearning();
 if(v==='understand'){sdStatus('sdTopicStatus','Nice progress! Saved as a growing strength. Try the practice worksheet to check your understanding.')}else if(v==='improve'){
 sdStatus('sdTopicStatus','Saved as a review priority. Use “Flashcards from my struggles” to practice it.');$('sdWorksheetBuild').focus()}
 else {sdStatus('sdTopicStatus','Let’s approach this another way…');lessonExplain('The learner needs more help. Use a simpler analogy and break the explanation into smaller steps, with one check question at a time.')}
});
async function makeWorksheet(){const topic=$('sdTopicInput').value.trim();if(!topic)return sdStatus('sdTopicStatus','Enter a topic first.');const btn=$('sdWorksheetBuild');btn.disabled=true;set('sdWorksheetOutput','Creating your original practice worksheet…');
 try{const answer=await ai('You are an original worksheet author for learners. Never reproduce material from third-party sites. Teach rather than evaluate high-stakes competency. '+context(),`Create an ORIGINAL practice worksheet for topic: ${topic}. Difficulty: ${$('sdWorksheetLevel').value}. Start with student name/date lines, followed by exactly 8 progressively challenging questions. Provide helpful working space prompts. End with a clearly separated ANSWER KEY and short explanations. Use plain readable text.`,2800);set('sdWorksheetOutput',answer);data.worksheets.unshift({id:id(),topic,text:answer,at:Date.now()});data.worksheets=data.worksheets.slice(0,20);save();}
 catch(e){set('sdWorksheetOutput','Could not generate the worksheet: '+e.message)}finally{btn.disabled=false}}
$('sdWorksheetBuild').onclick=makeWorksheet;$('sdTopicQuickPractice').onclick=makeWorksheet;
$('sdWorksheetCopy').onclick=async()=>{try{await navigator.clipboard.writeText($('sdWorksheetOutput').textContent);sdStatus('sdTopicStatus','Worksheet copied.')}catch{sdStatus('sdTopicStatus','Select the worksheet text and copy manually.')}};
$('sdWorksheetPrint').onclick=()=>{
 const content=$('sdWorksheetOutput').textContent;
 if(!content||content.includes('will appear'))return;
 const w=window.open('','_blank');
 if(!w){sdStatus('sdTopicStatus','Popup blocked. Use Copy worksheet instead.');return}
 const d=w.document;d.title='StudySpire Practice Worksheet';
 const heading=d.createElement('h2');heading.textContent='StudySpire Practice Worksheet';
 const pre=d.createElement('pre');pre.textContent=content;
 d.body.style.cssText='font:15px/1.65 Arial,sans-serif;max-width:740px;margin:35px auto;padding:20px';
 pre.style.cssText='white-space:pre-wrap;font:inherit';
 d.body.append(heading,pre);w.focus();w.print();
};
// Agenda keeps assignments separate from simple focus checklist, with real dates and completion state.
function renderAgenda(){const grid=$('sdCalendarGrid');grid.replaceChildren();const year=displayedMonth.getFullYear(),month=displayedMonth.getMonth();
 $('sdCalendarTitle').textContent=displayedMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'});
 const first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate(),today=sdDate(new Date());
 for(let i=0;i<first;i++)grid.append(sdCreate('div',undefined,'sd-calendar-blank'));
 for(let d=1;d<=days;d++){const date=sdDate(new Date(year,month,d)),items=data.assignments.filter(a=>a.due===date);
 const b=sdCreate('button',undefined,'sd-calendar-day'+(date===today?' today':'')+(date===selectedDate?' selected':''));b.type='button';b.setAttribute('aria-label',`${date}, ${items.length} assignments`);
 b.append(sdCreate('b',String(d)));if(items.length){const badge=sdCreate('small',String(items.length)+' task'+(items.length===1?'':'s'));b.append(badge);if(items.some(a=>!a.done))b.classList.add('has-work')};b.onclick=()=>{selectedDate=date;$('sdAssignmentDue').value=date;renderAgenda()};grid.append(b)}
 const list=$('sdAgendaDayList');list.replaceChildren();$('sdAgendaDayHeading').textContent='For '+new Date(selectedDate+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});
 const arr=data.assignments.filter(a=>a.due===selectedDate).sort((a,b)=>a.done-b.done);
 if(!arr.length)sdEmpty(list,'Nothing due on this date.');
 for(const item of arr){const row=sdCreate('div',undefined,'sd-agenda-row'+(item.done?' completed':'')),head=sdCreate('div',undefined,'sd-agenda-row-body');head.append(sdCreate('b',item.name));head.append(sdCreate('small',[item.course,item.type,item.notes].filter(Boolean).join(' · ')));
 const ch=sdCreate('input');ch.type='checkbox';ch.checked=!!item.done;ch.title='Mark complete';ch.onchange=()=>{item.done=ch.checked;save();renderAgenda();renderDashboard()};const del=sdCreate('button','×','sd-icon-del');del.title='Delete assignment';del.onclick=()=>{if(!confirm('Delete this assignment?'))return;data.assignments=data.assignments.filter(a=>a.id!==item.id);save();renderAgenda();renderDashboard()};row.append(ch,head,del);list.append(row)}renderDashboard()}
$('sdCalendarPrev').onclick=()=>{displayedMonth=new Date(displayedMonth.getFullYear(),displayedMonth.getMonth()-1,1);renderAgenda()};
$('sdCalendarNext').onclick=()=>{displayedMonth=new Date(displayedMonth.getFullYear(),displayedMonth.getMonth()+1,1);renderAgenda()};
$('sdCalendarToday').onclick=()=>{selectedDate=sdDate(new Date());displayedMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);$('sdAssignmentDue').value=selectedDate;renderAgenda()};
$('sdAgendaForm').onsubmit=e=>{e.preventDefault();const name=$('sdAssignmentName').value.trim(),due=$('sdAssignmentDue').value;if(!name||!due)return;
 data.assignments.push({id:id(),name:name.slice(0,160),course:$('sdAssignmentCourse').value.trim().slice(0,70),type:$('sdAssignmentType').value,notes:$('sdAssignmentNotes').value.trim().slice(0,400),due,done:false});save();selectedDate=due;displayedMonth=new Date(due+'T12:00:00');displayedMonth.setDate(1);$('sdAssignmentName').value='';$('sdAssignmentNotes').value='';renderAgenda()};
$('sdAssignmentDue').value=selectedDate;
function renderDashboard(){const box=$('sdDashboardAssignments');if(!box)return;box.replaceChildren();const open=data.assignments.filter(a=>!a.done).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5);if(!open.length)return sdEmpty(box,'Nothing due. Add an assignment in your agenda.');
 open.forEach(a=>{const r=sdCreate('div',undefined,'sd-agenda-row');r.append(sdCreate('div',a.due.slice(5),'sd-date-badge'));const t=sdCreate('div',undefined,'sd-agenda-row-body');t.append(sdCreate('b',a.name));t.append(sdCreate('small',a.course||a.type));r.append(t);box.append(r)})}
function renderDashboardSkills(){const box=$('sdDashboardSkills');if(!box)return;box.replaceChildren();const sorted=[...data.skills].sort((a,b)=>a.score-b.score).slice(0,4);if(!sorted.length)return sdEmpty(box,'Your topic ratings will appear here.');sorted.forEach(x=>{const r=sdCreate('div',undefined,'sd-dashboard-rating');r.append(sdCreate('span',x.name),sdCreate('b',x.score+'/100'));box.append(r)})}
// Friend lookup and chat: local demonstration between accounts on this one browser only.
const SOCIALKEY='sd-tutor-local-social-v1',ACCOUNTKEY='sd-tutor-local-accounts-v1';
function accounts(){try{return JSON.parse(localStorage.getItem(ACCOUNTKEY)||'{}')}catch{return {}}}
function social(){try{const o=JSON.parse(localStorage.getItem(SOCIALKEY)||'{}');return {requests:Array.isArray(o.requests)?o.requests:[],pairs:Array.isArray(o.pairs)?o.pairs:[],messages:Array.isArray(o.messages)?o.messages:[],decks:Array.isArray(o.decks)?o.decks:[]}}catch{return {requests:[],pairs:[],messages:[],decks:[]}}}
let socialData=social();function socialSave(){try{localStorage.setItem(SOCIALKEY,JSON.stringify(socialData))}catch{set('sdFriendStatus','Browser storage is full.')}}
const me=()=>sdAccountId(),pair=(a,b)=>[a,b].sort().join('|');
const isFriend=u=>socialData.pairs.includes(pair(me(),u));
function socialHint(msg){set('sdFriendStatus',msg)}
function renderSocial(){if(window.StudySummitMessagingBridge?.configured){window.StudySummitCloudMessaging?.refreshOnVisit?.();return}
 const who=me(),acc=accounts(),lock=window.StudySummitSafety?.status(who)||'',friends=socialData.pairs.filter(p=>p.split('|').includes(who)).map(p=>p.split('|').find(x=>x!==who)).filter(u=>!!acc[u]);
 const requestBox=$('sdFriendRequests'),friendBox=$('sdFriendsList'),sel=$('sdMessageFriend');requestBox.replaceChildren();friendBox.replaceChildren();$('sdSendMessage').disabled=!!lock;$('sdShareDeck').disabled=!!lock;if(lock)socialHint(lock);
 if(!who){sdEmpty(requestBox,'Sign in to a local profile first.');sdEmpty(friendBox,'Local profiles can try the friends demo.');sel.replaceChildren(new Option('Sign in first',''));renderThread();renderInbox();return}
 const inc=socialData.requests.filter(r=>r.to===who);if(!inc.length)sdEmpty(requestBox,'No pending requests.');
 inc.forEach(r=>{const row=sdCreate('div',undefined,'sd-agenda-row');row.append(sdCreate('span',r.from+' wants to connect'));const btn=sdCreate('button','Accept','btn primary small');btn.onclick=()=>{socialData.requests=socialData.requests.filter(x=>x!==r);if(!socialData.pairs.includes(pair(r.from,who)))socialData.pairs.push(pair(r.from,who));socialSave();renderSocial()};row.append(btn);requestBox.append(row)});
 if(!friends.length)sdEmpty(friendBox,'No friends yet. Search another local profile to send an invitation.');friends.forEach(u=>{const row=sdCreate('div',undefined,'sd-agenda-row');row.append(sdCreate('span','◉ '+u));const btn=sdCreate('button','Message','btn secondary small');btn.onclick=()=>{sel.value=u;renderThread();$('sdFriendMessage').focus()};row.append(btn);friendBox.append(row)});
 const prev=sel.value;sel.replaceChildren(new Option('Choose a friend',''),...friends.map(u=>new Option(u,u)));if(friends.includes(prev))sel.value=prev;renderThread();renderInbox()}
$('sdFriendFind').onclick=()=>{const box=$('sdFriendResults'),q=$('sdFriendSearch').value.trim().toLocaleLowerCase('en-US'),acc=accounts(),user=me();box.replaceChildren();if(!user)return sdEmpty(box,'Sign into a local profile to add friends.');if(!q)return sdEmpty(box,'Enter an exact username or email.');const entry=Object.entries(acc).find(([u,a])=>u.toLocaleLowerCase('en-US')===q||String(a.email||'').toLocaleLowerCase('en-US')===q);
 if(!entry)return sdEmpty(box,'No matching profile on this device.');const target=entry[0];if(target===user)return sdEmpty(box,'That is your own account.');
 const row=sdCreate('div',undefined,'sd-agenda-row');row.append(sdCreate('b',target));const button=sdCreate('button',isFriend(target)?'Already friends':'Send request','btn primary small');button.disabled=isFriend(target)||socialData.requests.some(r=>(r.from===user&&r.to===target)||(r.from===target&&r.to===user));if(button.disabled&&!isFriend(target))button.textContent='Request pending';button.onclick=()=>{socialData.requests.push({from:user,to:target,at:Date.now()});socialSave();socialHint('Request sent. That person can accept after signing into their profile on this device.');$('sdFriendFind').click()};row.append(button);box.append(row)};
$('sdFriendSearch').addEventListener('keydown',e=>{if(e.key==='Enter')$('sdFriendFind').click()});
function renderThread(){const box=$('sdMessageThread'),target=$('sdMessageFriend').value,who=me();box.replaceChildren();if(!who||!target||!isFriend(target))return sdEmpty(box,'Choose a friend to view messages.');
 const msgs=socialData.messages.filter(m=>(m.from===who&&m.to===target)||(m.from===target&&m.to===who)).slice(-100);if(!msgs.length)return sdEmpty(box,'No messages yet. Say hello!');
 msgs.forEach(m=>{const row=sdCreate('div',undefined,'sd-message-bubble'+(m.from===who?' mine':''));row.append(sdCreate('small',m.from+' · '+new Date(m.at).toLocaleString()));row.append(sdCreate('div',m.text));if(m.from!==who){const rep=sdCreate('button','Report message','ss-msg-report');rep.type='button';rep.title='Report this message to the local admin';rep.onclick=()=>{if(!confirm('Report this message for admin review?'))return;window.StudySummitSafety?.report(m.text,m.from,m.to);rep.disabled=true;rep.textContent='Reported';socialHint('Report saved for review by the local admin.')};row.append(rep)}box.append(row)});box.scrollTop=box.scrollHeight}
$('sdMessageFriend').onchange=renderThread;
$('sdSendMessage').onclick=()=>{const t=$('sdMessageFriend').value,m=$('sdFriendMessage').value.trim(),u=me();if(!u)return socialHint('Guest accounts cannot send messages. Sign in first.');if(!isFriend(t))return socialHint('Choose a local friend first.');if(!m)return;if(m.length>2000)return socialHint('Message is too long.');const check=window.StudySummitSafety?.review(m,{from:u,to:t})||{allowed:true};if(!check.allowed)return socialHint(check.reason);socialData.messages.push({id:id(),from:u,to:t,text:m,at:Date.now()});socialSave();$('sdFriendMessage').value='';renderThread();socialHint('Saved for this friend on this device.')};
$('sdShareDeck').onclick=()=>{const target=$('sdMessageFriend').value,who=me();if(!who||!isFriend(target))return socialHint('Sign in and choose a friend first.');const lock=window.StudySummitSafety?.status(who);if(lock)return socialHint(lock);if(!data.cards.length)return socialHint('Generate some flashcards first.');const deck={id:id(),from:who,to:target,cards:data.cards.map(c=>({front:c.front,back:c.back})).slice(0,25),at:Date.now()};const check=window.StudySummitSafety?.review(deck.cards.map(c=>c.front+' '+c.back).join(' ').slice(0,2000),{from:who,to:target})||{allowed:true};if(!check.allowed)return socialHint('Deck not shared: '+check.reason);socialData.decks.push(deck);socialSave();socialHint(`Shared ${deck.cards.length} flashcards with ${target} on this device.`)};
function renderInbox(){const box=$('sdSharedDeckInbox');box.replaceChildren();const list=socialData.decks.filter(d=>d.to===me()).slice(-20).reverse();if(!list.length)return sdEmpty(box,'No shared flashcards yet.');list.forEach(deck=>{const row=sdCreate('div',undefined,'sd-agenda-row');row.append(sdCreate('span',`${deck.cards.length} cards from ${deck.from}`));const btn=sdCreate('button','Import','btn secondary small');btn.onclick=()=>{data.cards=deck.cards.map(c=>({...c}));data.cardIndex=0;data.quizIndex=0;save();renderCard();showPane('quiz');socialHint('Imported a shared deck.')};row.append(btn);box.append(row)})}
